import codecs

def decode_chunks(chunks):
    decoder = codecs.getincrementaldecoder('utf-8-sig')()
    for chunk in chunks:
        yield decoder.decode(chunk)
    tail = decoder.decode(b'', final=True)
    if tail:
        yield tail

